#!/usr/bin/env bash
set -euo pipefail
_PASS="${COLABGAMING_KEY:?Chua nhap COLABGAMING_KEY}"

command -v openssl >/dev/null 2>&1 || { echo "Missing openssl" >&2; exit 1; }
_IN="$(mktemp)"
_TMP="$(mktemp)"
trap 'rm -f "$_IN" "$_TMP"' EXIT

awk 'found{print} /^#PAYLOAD:$/{found=1}' "$0" > "$_IN"
openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -salt -a -in "$_IN" -pass pass:"$_PASS" > "$_TMP"
chmod 700 "$_TMP"
exec bash "$_TMP" "$@"
#PAYLOAD:

